ALTER POLICY "Anyone can view lesson videos" ON public.course_lesson_videos TO authenticated USING (public.has_role(auth.uid(), 'admin') OR EXISTS (SELECT 1 FROM public.profiles WHERE user_id = auth.uid() AND has_paid_access = true));
ALTER POLICY "Anyone can view newsletter tips" ON public.newsletter_tips TO authenticated USING (public.has_role(auth.uid(), 'admin'));
ALTER POLICY "Authed view sections" ON public.email_template_sections USING (public.has_role(auth.uid(), 'admin'));
ALTER POLICY "Authed view variables" ON public.email_template_variables USING (public.has_role(auth.uid(), 'admin'));
ALTER POLICY "Authed view action items" ON public.email_template_action_items USING (public.has_role(auth.uid(), 'admin'));
ALTER POLICY "auth view templates" ON public.agenda_templates USING (public.has_role(auth.uid(), 'admin'));
ALTER POLICY "auth view template tasks" ON public.agenda_template_tasks USING (public.has_role(auth.uid(), 'admin'));
DROP POLICY "Anyone can insert download logs" ON public.resource_download_logs;
ALTER POLICY "Anyone can subscribe" ON public.email_subscribers WITH CHECK (is_active = true AND unsubscribed_at IS NULL AND char_length(email) BETWEEN 3 AND 254 AND email ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' AND char_length(coalesce(full_name,'')) <= 200 AND char_length(source) BETWEEN 1 AND 100);
ALTER POLICY "Anyone can submit an access request" ON public.coach_access_requests WITH CHECK (status = 'pending' AND reviewed_at IS NULL AND reviewed_by IS NULL AND char_length(full_name) BETWEEN 1 AND 200 AND char_length(email) BETWEEN 3 AND 254 AND email ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' AND char_length(college_name) BETWEEN 1 AND 300 AND char_length(coalesce(message,'')) <= 10000);
ALTER POLICY "Anyone can submit testimonials" ON public.testimonials WITH CHECK (public.has_role(auth.uid(), 'admin') OR (status = 'pending' AND coalesce(is_public,false) = false AND coalesce(is_featured,false) = false AND approved_at IS NULL AND published_at IS NULL AND entered_by IS NULL AND entered_at IS NULL AND admin_notes IS NULL AND curated_content IS NULL AND coalesce(display_order,0) = 0 AND source = 'form'));
ALTER POLICY "Anyone can submit coach message" ON public.player_coach_messages WITH CHECK (is_read = false AND char_length(coach_name) BETWEEN 1 AND 200 AND char_length(coach_email) BETWEEN 3 AND 254 AND coach_email ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' AND char_length(message) BETWEEN 1 AND 10000 AND EXISTS (SELECT 1 FROM public.players WHERE id = player_id AND is_active = true));
ALTER POLICY "Anyone can send a message to a coach" ON public.coach_messages WITH CHECK (is_read = false AND (sender_user_id IS NULL OR sender_user_id = auth.uid()) AND char_length(sender_name) BETWEEN 1 AND 200 AND char_length(sender_email) BETWEEN 3 AND 254 AND sender_email ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' AND char_length(message) BETWEEN 1 AND 10000 AND EXISTS (SELECT 1 FROM public.coaches WHERE id = coach_id AND is_active = true));
ALTER POLICY "Anyone can record a profile view" ON public.coach_profile_views WITH CHECK ((viewer_user_id = auth.uid() OR (viewer_user_id IS NULL AND viewer_full_name IS NULL AND viewer_graduation_year IS NULL AND viewer_handicap IS NULL AND char_length(viewer_session_id) BETWEEN 1 AND 200)) AND EXISTS (SELECT 1 FROM public.coaches WHERE id = coach_id AND is_active = true));
ALTER POLICY "Anyone can log visits" ON public.site_visitors WITH CHECK (char_length(visitor_id) BETWEEN 1 AND 200 AND char_length(page_url) BETWEEN 1 AND 2048 AND left(page_url,1) = '/' AND char_length(coalesce(referrer,'')) <= 4096 AND char_length(coalesce(user_agent,'')) <= 4096 AND ip_address IS NULL AND char_length(coalesce(country,'')) <= 200 AND char_length(coalesce(region,'')) <= 200 AND char_length(coalesce(city,'')) <= 200);
ALTER POLICY "Authenticated upload player-gallery" ON storage.objects WITH CHECK (bucket_id = 'player-gallery' AND (public.has_role(auth.uid(), 'admin') OR EXISTS (SELECT 1 FROM public.players p WHERE p.id::text = (storage.foldername(name))[1] AND p.user_id = auth.uid() AND p.allow_editing = true)));
ALTER POLICY "Authenticated update player-gallery" ON storage.objects USING (bucket_id = 'player-gallery' AND (public.has_role(auth.uid(), 'admin') OR EXISTS (SELECT 1 FROM public.players p WHERE p.id::text = (storage.foldername(name))[1] AND p.user_id = auth.uid() AND p.allow_editing = true))) WITH CHECK (bucket_id = 'player-gallery' AND (public.has_role(auth.uid(), 'admin') OR EXISTS (SELECT 1 FROM public.players p WHERE p.id::text = (storage.foldername(name))[1] AND p.user_id = auth.uid() AND p.allow_editing = true)));
ALTER POLICY "Authenticated delete player-gallery" ON storage.objects USING (bucket_id = 'player-gallery' AND (public.has_role(auth.uid(), 'admin') OR EXISTS (SELECT 1 FROM public.players p WHERE p.id::text = (storage.foldername(name))[1] AND p.user_id = auth.uid() AND p.allow_editing = true)));
ALTER POLICY "Public read free-resources" ON storage.objects USING (bucket_id = 'free-resources' AND (public.has_role(auth.uid(), 'admin') OR EXISTS (SELECT 1 FROM public.free_resources r WHERE r.is_active = true AND r.file_path = name)));
ALTER POLICY "Public can read free-resources objects" ON storage.objects USING (bucket_id = 'free-resources' AND (public.has_role(auth.uid(), 'admin') OR EXISTS (SELECT 1 FROM public.free_resources r WHERE r.is_active = true AND r.file_path = name)));
ALTER POLICY "Testimonial images are publicly readable" ON storage.objects USING (bucket_id = 'testimonial-images' AND (public.has_role(auth.uid(), 'admin') OR EXISTS (SELECT 1 FROM public.testimonials t WHERE t.image_url = name AND t.is_public = true AND t.status IN ('approved','published'))));